 static Item Item(string key,string status,string value){return new Item(key,status,"独立临时浏览器会话 / 两个 STUN 来源",value,"单次无摄像头、麦克风或个人浏览器配置；与日常浏览器策略可能不同，不代表无泄漏。","");}
 static List<Item> Missing(string value,string failure="unavailable",string phase="browser"){var items=new List<Item>{Item("ext-rtc-browser","unknown",value),Item("ext-rtc-path","unknown","未取得候选类型或传输证据"),Item("ext-rtc-compare","unknown","无法与本轮出口比较")};foreach(var i in items){i.evidencePhase=phase;i.failureCode=failure;i.evidenceScope="isolated-browser;two-stun";}return items;}
