 static List<string> Browsers(){var found=new List<string>();foreach(var root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)})foreach(var suffix in new[]{@"Microsoft\Edge\Application\msedge.exe",@"Google\Chrome\Application\chrome.exe"}){string p=Path.Combine(root,suffix);if(File.Exists(p)&&!found.Contains(p,StringComparer.OrdinalIgnoreCase))found.Add(p);}return found;}
 static string Token(){byte[] data=new byte[16];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(data);return BitConverter.ToString(data).Replace("-","").ToLowerInvariant();}
 static void Response(NetworkStream stream,int status,string content,string type){byte[] body=Encoding.UTF8.GetBytes(content);byte[] header=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+(status==200?" OK":" Forbidden")+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+body.Length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(body,0,body.Length);}
 static string Page(string token){return @"<!doctype html><meta charset='utf-8'><title>临时 ICE 检查</title><script>
 (async()=>{let done=false,overflow=false,errors=[],entries=[],pc;async function finish(error){if(done)return;done=true;try{if(pc)pc.close()}catch(e){}try{await fetch('/"+token+@"',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidates:entries,error:error||(overflow?'candidate limit':errors.join(','))})})}catch(e){}}
 try{pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.cloudflare.com:3478'},{urls:'stun:stun.l.google.com:19302'}]});try{await fetch('/"+token+@"',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phase:'ice-started'})})}catch(e){}pc.createDataChannel('check');pc.onicecandidateerror=e=>{if(errors.length<4)errors.push((e.url||'STUN')+' ICE '+e.errorCode)};pc.onicecandidate=e=>{if(!e.candidate)return finish('');if(entries.length<32)entries.push({type:e.candidate.type||'',protocol:e.candidate.protocol||'',address:e.candidate.address||''});else overflow=true};let offer=await pc.createOffer();await pc.setLocalDescription(offer);setTimeout(()=>finish('gather timeout'),6000)}catch(e){finish(String(e))}})();</script>";}
 static void CheckDeadline(Stopwatch sw,CancellationToken token,int deadline){token.ThrowIfCancellationRequested();if(sw.ElapsedMilliseconds>=deadline)throw new TimeoutException();}
 public static bool ValidHeader(string raw,string token,int port,out bool post,out int length){post=false;length=0;if(String.IsNullOrEmpty(raw)||!raw.EndsWith("\r\n\r\n")||raw.Length>8192)return false;string[] lines=raw.Split(new[]{"\r\n"},StringSplitOptions.None);string[] first=lines[0].Split(' ');if(first.Length!=3||first[1]!="/"+token||(first[2]!="HTTP/1.1"&&first[2]!="HTTP/1.0"))return false;string host="",origin="",content="";bool seenLength=false;foreach(string line in lines.Skip(1)){int sep=line.IndexOf(':');if(sep<0)continue;string k=line.Substring(0,sep).Trim().ToLowerInvariant(),v=line.Substring(sep+1).Trim();if(k=="host"){if(host!="")return false;host=v;}if(k=="origin"){if(origin!="")return false;origin=v;}if(k=="content-type"){if(content!="")return false;content=v;}if(k=="transfer-encoding")return false;if(k=="content-length"){if(seenLength||!Int32.TryParse(v,out length))return false;seenLength=true;}}string expected="127.0.0.1:"+port;if(host!=expected)return false;if(first[0]=="GET")return !seenLength||length==0;post=first[0]=="POST";return post&&origin=="http://"+expected&&content.Split(';')[0].Trim().Equals("application/json",StringComparison.OrdinalIgnoreCase)&&seenLength&&length>=2&&length<=16384;}
 static string ReadRequest(TcpClient client,string token,int port,Stopwatch sw,CancellationToken cancel,int deadline,out bool isPost){
  isPost=false;client.ReceiveTimeout=250;client.SendTimeout=250;var stream=client.GetStream();var header=new List<byte>();bool complete=false;while(header.Count<8192){CheckDeadline(sw,cancel,deadline);int b=stream.ReadByte();if(b<0)break;header.Add((byte)b);int n=header.Count;if(n>=4&&header[n-4]==13&&header[n-3]==10&&header[n-2]==13&&header[n-1]==10){complete=true;break;}}if(!complete)return null;string raw=Encoding.ASCII.GetString(header.ToArray());bool post;int length;if(!ValidHeader(raw,token,port,out post,out length))return null;if(!post){Response(stream,200,Page(token),"text/html");return "";}byte[] payload=new byte[length];int pos=0;while(pos<length){CheckDeadline(sw,cancel,deadline);int n=stream.Read(payload,pos,length-pos);if(n<=0)return null;pos+=n;}Response(stream,200,"ok","text/plain");isPost=true;return Encoding.UTF8.GetString(payload);
 }
 sealed class BrowserExitedException:Exception {public readonly int ExitCode;public BrowserExitedException(int code){ExitCode=code;}}
 static string Receive(TcpListener listener,Process browser,IntPtr job,string token,int port,CancellationToken cancel,int deadline,ref bool pageServed,ref bool iceStarted){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<deadline&&!cancel.IsCancellationRequested){if(listener.Pending()){using(var client=listener.AcceptTcpClient()){var remote=client.Client.RemoteEndPoint as IPEndPoint;if(remote==null||!IPAddress.IsLoopback(remote.Address))continue;try{bool posted;string value=ReadRequest(client,token,port,sw,cancel,deadline,out posted);if(posted){bool progress=false;try{var marker=new JavaScriptSerializer().DeserializeObject(value) as Dictionary<string,object>;progress=marker!=null&&marker.Count==1&&marker.ContainsKey("phase")&&Convert.ToString(marker["phase"])=="ice-started";}catch{}if(progress){iceStarted=true;continue;}return value;}if(value=="")pageServed=true;else if(value==null)Response(client.GetStream(),403,"forbidden","text/plain");}catch(IOException){}}continue;}if(browser.HasExited){Accounting accounting;if(QueryInformationJobObject(job,1,out accounting,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero)&&accounting.activeProcesses==0)throw new BrowserExitedException(browser.ExitCode);}Thread.Sleep(30);}if(cancel.IsCancellationRequested)throw new OperationCanceledException();throw new TimeoutException();} static Process StartContained(string executable,string args,IntPtr job){var startup=new Startup();startup.cb=Marshal.SizeOf(typeof(Startup));startup.flags=1;startup.show=0;ProcInfo info;var command=new StringBuilder("\""+executable+"\" "+args);if(!CreateProcess(executable,command,IntPtr.Zero,IntPtr.Zero,false,0x08000004,IntPtr.Zero,null,ref startup,out info))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"无法启动隔离浏览器");try{if(!AssignProcessToJobObject(job,info.process)){TerminateProcess(info.process,1);throw new InvalidOperationException("无法隔离浏览器进程组");}var owned=Process.GetProcessById((int)info.processId);try{IntPtr processHandle=owned.Handle;if(ResumeThread(info.thread)==UInt32.MaxValue){TerminateProcess(info.process,1);throw new InvalidOperationException("无法启动隔离浏览器线程");}return owned;}catch{owned.Dispose();throw;}}finally{CloseHandle(info.thread);CloseHandle(info.process);}}
 static void RemoveOwnDirectory(string root,string directory){string actual=WorkPaths.CanonicalDirectory(directory);if(!actual.Equals(directory,StringComparison.OrdinalIgnoreCase)||!actual.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(actual).StartsWith("ice-",StringComparison.Ordinal))throw new IOException("临时目录落点已改变");var pending=new Stack<string>();pending.Push(actual);int count=0;while(pending.Count>0){foreach(string entry in Directory.GetFileSystemEntries(pending.Pop())){if(++count>10000)throw new IOException("临时目录内容过多");var attrs=File.GetAttributes(entry);if((attrs&FileAttributes.ReparsePoint)!=0)throw new IOException("临时目录含重解析点");if((attrs&FileAttributes.Directory)!=0)pending.Push(entry);}}Directory.Delete(actual,true);}
 static bool Public(IPAddress a){byte[] b=a.GetAddressBytes();if(IPAddress.IsLoopback(a)||a.Equals(IPAddress.Any)||a.Equals(IPAddress.IPv6Any)||a.IsIPv6LinkLocal||a.IsIPv6Multicast||a.IsIPv6SiteLocal)return false;if(a.AddressFamily==AddressFamily.InterNetwork)return b[0]!=0&&b[0]!=10&&b[0]!=127&&b[0]<224&&!(b[0]==169&&b[1]==254)&&!(b[0]==172&&b[1]>=16&&b[1]<=31)&&!(b[0]==192&&b[1]==168)&&!(b[0]==100&&b[1]>=64&&b[1]<=127);return (b[0]&0xfe)!=0xfc;}
 static bool BaselineFresh(Item item){DateTimeOffset at;if(item==null||!DateTimeOffset.TryParse(item.observedAt,out at))return false;double age=(DateTimeOffset.Now-at).TotalSeconds;return age>=0&&age<30;} public static List<Item> Interpret(string json,string browser,Report baseline){try{if(json==null||json.Length>16384)return Missing("浏览器结果长度无效");return InterpretCore(json,browser,baseline);}catch(Exception){return Missing("浏览器结果格式不可验证");}}
 static List<Item> InterpretCore(string json,string browser,Report baseline){var root=new JavaScriptSerializer().DeserializeObject(json) as Dictionary<string,object>;object raw,errorRaw;var array=root!=null&&root.TryGetValue("candidates",out raw)?raw as object[]:null;if(array==null||!root.TryGetValue("error",out errorRaw)||!(errorRaw is string))return Missing("浏览器结果格式不可验证","invalid-result","return");string error=(string)errorRaw;bool complete=String.IsNullOrEmpty(error)&&array.Length<=32;if(array.Length>32)error="候选数量超出上限";var candidates=new List<Dictionary<string,object>>();foreach(var row in array.Take(32)){var entry=row as Dictionary<string,object>;if(entry!=null)candidates.Add(entry);else{complete=false;error="候选格式无效";}}if(candidates.Count==0)return Missing(complete?"浏览器未返回 ICE 候选":"浏览器收集不完整："+error,complete?"no-candidates":"ice-incomplete","ice");
  Func<Dictionary<string,object>,string,string> field=(x,k)=>x.ContainsKey(k)?Convert.ToString(x[k]):"";if(candidates.Any(x=>!new[]{"host","srflx","prflx","relay"}.Contains(field(x,"type"))||!new[]{"udp","tcp"}.Contains(field(x,"protocol")))){complete=false;error="候选类型或传输格式不完整";}var types=candidates.Select(x=>field(x,"type")+"/"+field(x,"protocol")).Where(x=>x!="/").Distinct().Take(8).ToArray();var exits=baseline.items.Where(i=>i.key=="ipv4-source"&&i.status=="pass"&&BaselineFresh(i)).Select(i=>i.observation).ToArray();string v4=exits.Length==2&&exits[0]==exits[1]?exits[0]:null;var ipv6=baseline.items.FirstOrDefault(i=>i.key=="ipv6-public"&&i.status=="pass"&&BaselineFresh(i));IPAddress expected6;string v6=ipv6!=null&&IPAddress.TryParse(ipv6.observation,out expected6)&&expected6.AddressFamily==AddressFamily.InterNetworkV6?expected6.ToString():null;bool missing=false,different=false,compared4=false,compared6=false;int compared=0;var paths=baseline.items.Where(i=>i.key=="ipv6-path").ToList();DateTimeOffset pathAt;bool controlled=paths.Count>0&&ipv6==null&&paths.Select(i=>i.identity).Distinct().Count()==1&&paths.All(i=>i.status=="pass"&&(i.identity=="ipv6-path-no-path"||i.identity=="ipv6-path-blocked")&&DateTimeOffset.TryParse(i.observedAt,out pathAt)&&(DateTimeOffset.Now-pathAt).TotalSeconds>=0&&(DateTimeOffset.Now-pathAt).TotalSeconds<30);
  foreach(var entry in candidates){string kind=field(entry,"type"),text=field(entry,"address");if(kind=="relay"){missing=true;continue;}if(kind!="host"&&kind!="srflx"&&kind!="prflx")continue;IPAddress candidate;if(!IPAddress.TryParse(text,out candidate)){missing=true;continue;}if(!Public(candidate))continue;string expected=candidate.AddressFamily==AddressFamily.InterNetwork?v4:v6;if(expected==null){missing=true;continue;}IPAddress parsed;if(!IPAddress.TryParse(expected,out parsed)){missing=true;continue;}compared++;if(candidate.AddressFamily==AddressFamily.InterNetwork)compared4=true;else compared6=true;if(!candidate.Equals(parsed))different=true;}
  string status=different?"attention":complete&&!missing&&compared>0&&compared4&&(compared6||controlled)?"pass":"unknown";string compare=different?"观察到公网 host/srflx 与同族出口不同；差异不等于泄漏":status=="pass"?(controlled&&!compared6?"已观察 IPv4 与同族出口一致；IPv6 本轮有路径控制证据，未观察到不等于不泄漏":"已观察公网 host/srflx 与同族出口一致；未观察到不等于不泄漏"):"候选不完整、未解析或缺少同族出口与 IPv6 路径依据，无法全面比较";
  var output=new List<Item>{Item("ext-rtc-browser",complete?"pass":"unknown",Path.GetFileName(browser)+" 独立临时会话；"+(complete?"完成":"部分/超时")+"，候选 "+candidates.Count+" 个"+(complete?"":"；"+error)),Item("ext-rtc-path",complete&&types.Length>0?"pass":"unknown",types.Length>0?String.Join("、",types)+(complete?"":"（部分）"):"未取得候选类型"),Item("ext-rtc-compare",status,compare)};foreach(var item in output){item.evidencePhase="ice-return";item.failureCode=complete?null:"ice-incomplete";item.evidenceScope="isolated-browser;two-stun";}return output;
 }
 public static List<Item> Collect(Report baseline,string workRoot,CancellationToken cancel){var browsers=Browsers();if(browsers.Count==0)return Missing("未找到受支持的隔离浏览器","browser-missing","browser-start");string baseDir;try{baseDir=WorkPaths.PrivateDirectory(workRoot);}catch{return Missing("未提供可核验的私密测试工作目录","invalid-work-directory","session");}return TryBrowsers(browsers,cancel,delegate(string executable){return CollectExecutable(baseline,baseDir,cancel,executable,11000,null,RemoveOwnDirectory,null);});}
 static List<Item> TryBrowsers(IEnumerable<string> browsers,CancellationToken cancel,Func<string,List<Item>> attempt){List<Item> result=null;foreach(string executable in browsers.Take(2)){if(cancel.IsCancellationRequested)break;result=attempt(executable);var first=result.FirstOrDefault(i=>i.key=="ext-rtc-browser");if(first==null||first.evidencePhase!="browser-start"||first.failureCode!="tool-failed")break;}return result??Missing("浏览器检查已取消","cancelled","browser-start");}
 static List<Item> CollectExecutable(Report baseline,string baseDir,CancellationToken cancel,string executable,int deadline,Func<int,string,string,string> fixtureArgs,Action<string,string> cleanup,Action<string> created){string directory=Path.GetFullPath(Path.Combine(baseDir,"ice-"+Guid.NewGuid().ToString("N")));if(!directory.StartsWith(baseDir+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return Missing("临时目录不安全","invalid-work-directory","session");string owner=Token(),marker=Path.Combine(directory,".workenv-owner");try{if(!CreateOwnDirectory(directory,IntPtr.Zero))return Missing("临时会话目录创建失败","session-create-failed","session");using(var stream=new FileStream(marker,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var writer=new StreamWriter(stream,Encoding.ASCII))writer.Write(owner);if(created!=null)created(directory);}catch{return Missing("临时会话目录创建失败","session-create-failed","session");}IntPtr job=IntPtr.Zero;Process process=null;TcpListener listener=null;var outcome=new List<Item>();bool pageServed=false,iceStarted=false;string stage="session";
  try{cancel.ThrowIfCancellationRequested();listener=new TcpListener(IPAddress.Loopback,0);listener.Start(2);int port=((IPEndPoint)listener.LocalEndpoint).Port;string token=Token();job=CreateJobObject(IntPtr.Zero,null);if(job==IntPtr.Zero)throw new InvalidOperationException("无法建立独立进程组");var info=new Extended();info.basic.flags=0x2000;if(!SetInformationJobObject(job,9,ref info,(uint)Marshal.SizeOf(typeof(Extended))))throw new InvalidOperationException("无法设置进程组清理");stage="browser-start";
